    public static function key(string $source):string{return'finance_preferences_'.substr(hash('sha256',$source),0,24);}
    public static function messages(string $locale):array{$out=[];$en=explode('-',$locale,2)[0]==='en';foreach(self::ENGLISH as$source=>$translation)$out[self::key($source)]=$en?$translation:$source;return$out;}
    public static function text(string $source,array $messages):string
    {
        if(isset($messages[self::key($source)]))return$messages[self::key($source)];
        if(preg_match('/\A(.+) · Unterteilung ([1-4][1-9])\z/uD',$source,$parts))return self::text($parts[1],$messages).' · '.self::text('Unterteilung',$messages).' '.$parts[2];
        if(preg_match('/\ASteuerkonto ([0-9]{5}) ist für ([0-9]{4}) nicht im Kontenplan dieses Vereins vorhanden\.\z/D',$source,$parts)&&isset($messages[self::key('Steuerkonten')])&&$messages[self::key('Steuerkonten')]==='Tax accounts')return'Tax account '.$parts[1].' is not in this club’s chart of accounts for '.$parts[2].'.';
        return GeneralSettingsMessages::text($source,$messages);
    }
